UPDATE dashboard SET config=json_insert(config,'$.tools[#]',json('{"id":"partners","name":"Firmen- & Vereinsfitness","description":"Kooperationen suchen, Konditionen prüfen und Partner verwalten","url":"","icon":"members","color":"blue","kind":"partners"}')),revision=revision+1 WHERE NOT EXISTS(SELECT 1 FROM json_each(dashboard.config,'$.tools') WHERE json_extract(value,'$.kind')='partners');